package terraform

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/hashicorp/terraform/internal/lang/marks"
	"github.com/zclconf/go-cty/cty"
)

// filterMarks removes any PathValueMarks from marks which cannot be applied to
// the given value. When comparing existing marks to those from a map or other
// dynamic value, we may not have values at the same paths and need to strip
// out irrelevant marks.
func filterMarks(val cty.Value, markList []cty.PathValueMarks) []cty.PathValueMarks {
	var res []cty.PathValueMarks
	if len(markList) == 0 {
		return res
	}

	containsSensitive := false
	unmarkedVal := val
	typeName := ""
	if val != cty.NilVal {
		containsSensitive = marks.Contains(val, marks.Sensitive)
		if val.ContainsMarked() {
			unmarkedVal, _ = val.UnmarkDeepWithPaths()
		}
		typeName = unmarkedVal.Type().FriendlyName()
	}

	pathApplies := make(map[string]bool, len(markList))

	for _, pvm := range markList {
		current := val
		applicable := true
		copiedPath := make(cty.Path, len(pvm.Path))
		copy(copiedPath, pvm.Path)
		keyParts := make([]string, 0, len(copiedPath))

		for _, step := range copiedPath {
			if !applicable {
				break
			}

			switch s := step.(type) {
			case cty.GetAttrStep:
				attrName := s.Name
				keyParts = append(keyParts, attrName)
				if current.IsNull() {
					applicable = false
					continue
				}
				currentTy := current.Type()
				if !currentTy.IsObjectType() {
					applicable = false
					continue
				}
				if !currentTy.HasAttribute(attrName) {
					applicable = false
					continue
				}
				attrVal := current.GetAttr(attrName)
				if marks.Has(attrVal, marks.Sensitive) {
					keyParts[len(keyParts)-1] = attrName
				}
				current = attrVal
			case cty.IndexStep:
				keyTy := s.Key.Type()
				if keyTy == cty.String {
					keyParts = append(keyParts, s.Key.AsString())
				}
				if keyTy == cty.Number {
					idx, _ := s.Key.AsBigFloat().Int64()
					keyParts = append(keyParts, strconv.Itoa(int(idx)))
				}
				next, err := s.Apply(current)
				if err != nil {
					applicable = false
					continue
				}
				current = next
			}
		}

		pathKey := strings.Join(keyParts, ".")
		if containsSensitive {
			pathKey = pathKey + ":" + typeName
		}
		if pathApplies[pathKey] {
			res = append(res, pvm)
			continue
		}
		pathApplies[pathKey] = applicable
		if applicable {
			res = append(res, pvm)
		}
	}

	return res
}

// marksEqual compares 2 unordered sets of PathValue marks for equality, with
// the comparison using the cty.PathValueMarks.Equal method.
func marksEqual(a, b []cty.PathValueMarks) bool {
	if len(a) == 0 && len(b) == 0 {
		return true
	}

	if len(a) != len(b) {
		return false
	}

	less := func(s []cty.PathValueMarks) func(i, j int) bool {
		return func(i, j int) bool {
			// the sort only needs to be consistent, so use the GoString format
			// to get a comparable value
			return fmt.Sprintf("%#v", s[i]) < fmt.Sprintf("%#v", s[j])
		}
	}

	sort.Slice(a, less(a))
	sort.Slice(b, less(b))

	for i := 0; i < len(a); i++ {
		if !a[i].Equal(b[i]) {
			return false
		}
	}

	return true
}

// Remove duplicate PathValueMarks from the slice.
// When adding marks from a resource schema to a value, most of the time there
// will be duplicates from a prior value already in the list of marks. While
// MarkwithPaths will accept duplicates, we need to be able to easily compare
// the PathValueMarks within this package too.
func dedupePathValueMarks(m []cty.PathValueMarks) []cty.PathValueMarks {
	var res []cty.PathValueMarks
	// we'll use a GoString format key to differentiate PathValueMarks, since
	// the Path portion is not automagically comparable.
	seen := make(map[string]bool)

	for _, pvm := range m {
		key := fmt.Sprintf("%#v", pvm)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = true
		res = append(res, pvm)
	}

	return res
}

